func Keep(seq iter.Seq[Msg], pred func(Msg) bool) iter.Seq[Msg] {
    return func(yield func(Msg) bool) {
        for m := range seq {
            if pred(m) && !yield(m) { return }   // consumer stopped pulling
        }
    }
}
